# Check all demos for common pattern
import json

with open('/home/ubuntu/runs/paper/qwen-hpl0-u1-turns/play/users/u000/system/state/workspace/programs/task-a64db3e2.json') as f:
    data = json.load(f)

def find_horizontal_run(grid, r, c, value):
    """Find consecutive cells of same value starting from current position"""
    left = 0
    right = 0
    h, w = len(grid), len(grid[0]) if grid else 0
    # Scan left
    for i in range(c-1, -1, -1):
        if grid[r][i] == value:
            left += 1
        else:
            break
    # Scan right
    for i in range(c+1, w):
        if grid[r][i] == value:
            right += 1
        else:
            break
    return left, right

def find_vertical_run(grid, r, c, value):
    """Find consecutive cells of same value starting from current position"""
    up = 0
    down = 0
    h, w = len(grid), len(grid[0]) if grid else 0
    # Scan up
    for i in range(r-1, -1, -1):
        if grid[i][c] == value:
            up += 1
        else:
            break
    # Scan down
    for i in range(r+1, h):
        if grid[i][c] == value:
            down += 1
        else:
            break
    return up, down

print("=== Analyzing change cells ===")
for i, pair in enumerate(data, 1):
    inp = pair['input']
    out = pair['output']
    h, w = len(inp), len(inp[0])
    changes = [(r, c) for r in range(h) for c in range(w) if inp[r][c] != out[r][c]]

    print(f"\nDemo {i}: {len(changes)} changes")
    for r, c in changes:
        val = inp[r][c]
        left, right = find_horizontal_run(inp, r, c, val)
        up, down = find_vertical_run(inp, r, c, val)
        print(f"  ({r},{c}): val={val}, run(left={left},right={right},up={up},down={down})")
        # Also check the opposing direction
        right2, left2 = left+1 if c < w-1 else 0, 0
        left2 = 0
        for j in range(c-1, -1, -1):
            if inp[r][j] == val:
                left2 += 1
            else:
                break
        for j in range(c+1, w):
            if inp[r][j] == val:
                right2 += 1
            else:
                break
        print(f"    More detailed: left={left2}, right={right2}, up={up}, down={down}")
        # Score: maybe it's about touching "corners" = having long runs in 2+ directions?
        print(f"    Left+Up runs VS Left+Down OR Right+UP VS Right+Down: ({left2+up}-{up} vs {left2+down}-{down})")

